const recordIndex = new Map(EQUIPMENT_RECORDS.map((record) => [`${record.equipment}:${record.room}`, record]));
export function equipmentRecord(equipment: EquipmentId, room: number): EquipmentRecord | null { return recordIndex.get(`${equipment}:${room}`) || null; }
export function equipmentIsDefined(record: EquipmentRecord | null): record is EquipmentRecord { return Boolean(record?.productCode && record?.tipExcel); }
